  function syncStrategy(){const root=q('[data-opt-config-v069]',ctl.host);if(!root)return;const strategy=q('[data-opt-strategy-v069]',root)?.value||'sweep';const sweep=strategy==='sweep';qa('.opt-levels-v069',root).forEach(el=>el.classList.toggle('hidden',!sweep));qa('[data-opt-objectives-v069]',root).forEach(el=>el.closest('article')?.classList.toggle('required-v069',isMulti(strategyMode(strategy))));ctl.preview=null;const button=q('[data-opt-submit-v069]',root);if(button)button.disabled=true;updateWizardSummary()}
