    const constraints=qa('[data-opt-constraint-row-v069]',root).map(row=>({field:`result.${q('[data-opt-constraint-id-v069]',row).value}`,operator:q('[data-opt-constraint-operator-v069]',row).value,value:Number(q('[data-opt-constraint-value-v069]',row).value),aggregation:q('[data-opt-constraint-aggregation-v074b]',row)?.value||'all_points',percentile:95}));
