    const robustness={enabled:robustEnabled,samples:Number(q('[data-opt-robust-samples-v074c]',root)?.value||8),seed:7403,include_nominal:true,sampling:q('[data-opt-robust-sampling-v074c]',root)?.value||'latin_hypercube',distributions:robustEnabled?distributions:[],objective_strategy:q('[data-opt-robust-objective-v074c]',root)?.value||'risk_adjusted_mean',risk_weight:Number(q('[data-opt-robust-risk-v074c]',root)?.value||1),percentile:95,constraint_strategy:q('[data-opt-robust-constraint-v074c]',root)?.value||'probability',required_feasibility_probability:Number(q('[data-opt-robust-probability-v074c]',root)?.value||0.95)};
    const sensitivity={enabled:Boolean(q('[data-opt-sensitivity-enabled-v074c]',root)?.checked),methods:['local','morris','sobol'],output_ids:objectives.map(o=>o.result_id)};
    return {experiment:{mode,variables,samples:Number(q('[data-opt-samples-v069]',root)?.value||20),seed:Number(q('[data-opt-seed-v069]',root)?.value||42),include_baseline:Boolean(q('[data-opt-baseline-v069]',root)?.checked),objectives,constraints,population_size:Number(q('[data-opt-population-v069]',root)?.value||16),generations:Number(q('[data-opt-generations-v069]',root)?.value||4),crossover_rate:.9,mutation_rate:.15,robustness,sensitivity},operating_points,load_case_index:Number(operating_points[0].load_case_index),expected_analysis_revision_id:ctl.catalog.analysis_revision_id,expected_design_revision_id:ctl.catalog.design_revision_id,reuse_cache:true,run_native_precheck:false};
