  async function preview(){const root=q('[data-opt-config-v069]',ctl.host),box=q('[data-opt-preview-result-v069]',root),button=q('[data-opt-preview-v069]',root);button.disabled=true;button.textContent='正在检查…';try{const payload=collect();ctl.preview=await api(`/api/analysis-definitions/${encodeURIComponent(ctl.analysisId)}/experiments/preview`,{method:'POST',body:JSON.stringify(payload),signal:ctl.ctx?.signal});if(!active(ctl.ctx))return;const p=ctl.preview,estimate=p.estimate||{},blocking=Number(p.task_validation?.blocking||0)+Number(p.studio_precheck?.blocking||0),ops=p.operating_point_set?.points||[],unc=p.uncertainty_scenario_set?.samples||[],uncCount=Number(estimate.uncertainty_sample_count||unc.length||1);box.innerHTML=`<div class="opt-preview-v069 ${p.can_submit?'ready':'blocked'}"><div><span>候选 × 扰动 × 工况</span><b>${safe(estimate.candidate_count||estimate.initial_cases||0)} × ${safe(uncCount)} × ${safe(estimate.operating_point_count||ops.length||1)}</b><small>共 ${safe(estimate.estimated_total_cases||0)} 个计算工况 · ${safe(estimate.mode||'')}</small></div><div><span>冻结合同</span><b>${safe(ops.length)} OP · ${safe(uncCount)} uncertainty</b><small>OP ${safe(String(p.operating_point_set_hash||'').slice(0,8))} · UNC ${safe(String(p.uncertainty_scenario_set_hash||'nominal').slice(0,8))} · Plan ${safe(String(p.experiment_plan_hash||'').slice(0,8))}</small></div><div><span>鲁棒策略</span><b>${p.robustness_plan?safe(p.robustness_plan.objective_strategy):'名义评价'}</b><small>${p.robustness_plan?`约束 ${safe(p.robustness_plan.constraint_strategy)} · P≥${fmt(p.robustness_plan.required_feasibility_probability,2)}`:'未启用不确定性采样'}</small></div><div><span>Studio / 运行环境</span><b>${blocking?'存在阻断':p.runtime_readiness?.ok?'可提交':'运行环境未就绪'}</b><small>${safe((p.warnings||[]).map(x=>x.message).join('；')||p.runtime_readiness?.message||'参数、聚合与任务合同有效')}</small></div></div>`;q('[data-opt-submit-v069]',root).disabled=!p.can_submit;updateWizardSummary()}catch(error){ctl.preview=null;box.innerHTML=`<div class="issue BLOCKING"><b>计划检查失败</b> ${safe(error.message||error)}</div>`}finally{button.disabled=false;button.textContent='生成计划并检查'}}
